final int LATEST_THEME_FILE_VERSION = 0;

JSONArray themes;

int THEME_BACKGROUND_COL, THEME_FOREGROUND_COL, THEME_HIGHLIGHT_COL, THEME_ERROR_MAJOR_COL, THEME_UNAVAILABLE_COL;
